import { Injectable } from '@angular/core';
import { httpResource } from '@angular/common/http';

/** Results bundle generated by research/build_results.py (frontend/public/data/results.json). */
export interface HoldoutRow {
  name: string; f1: number; f1_ci: [number, number] | null;
  pr_auc: number; pr_auc_ci: [number, number] | null;
  roc_auc: number; roc_auc_ci: [number, number] | null;
  recall: number | null; precision: number | null;
}
export interface ReplicationSummary {
  label: string; roc_auc: number; roc_auc_std: number | null;
  recall_fp: number; precision_fp: number; recall_confirmed: number; precision_confirmed: number;
}
export interface Results {
  generated_utc: string;
  dataset: Record<string, number>;
  feature_sets: { key: string; label: string; n: number }[];
  cv_f1: { name: string; f1: number[] }[];
  pr_auc_11: { name: string; pr_auc: number }[];
  selection: { name: string; cv_pr_auc: number }[];
  holdout: HoldoutRow[];
  confusion_matrix: number[][];
  thresholds: {
    default: { t: number; precision: number; recall: number };
    high_precision: { t: number; precision: number; recall: number };
    curve: { t: number; precision: number; recall: number; f1: number }[];
    curve_source: string;
  };
  importance: { feature: string; drop: number }[];
  replication: {
    rows_after_dropna: number; rows_reported_in_text: number; protocol: string[];
    rows: ReplicationSummary[]; sweep: { trial: number; layers: number[]; roc_auc: number; paper_roc_auc: number }[];
    ambiguities: string[];
  };
  prioritisation: PrioritisationSummary;
}
export interface PrioritisationSummary {
  n_candidates: number; n_dropped_missing_prad_or_insol: number; n_scored_ess: number; n_pareto: number;
  p_planet: Record<string, number>; ess: Record<string, number>;
  sensitivity: Record<string, { spearman: number; top20_overlap: number }>;
  nasa_check: {
    ok: boolean; informative: boolean; queried_utc: string;
    attempts: { method: string; ok: boolean; rows?: number; error?: string }[];
    by_probability_rank?: Record<string, Record<string, number>>;
    resolved_since_snapshot?: number; resolved_roc_auc?: number; resolved_pr_auc?: number;
    resolved_confirmed_share?: number;
  };
}
export interface Candidate {
  rank: number; kepoi_name: string; kepler_name: string | null; koi_period: number | null;
  koi_prad: number; koi_insol: number; koi_teq: number | null; koi_steff: number | null;
  p_planet: number; ess: number; priority: number; pareto: boolean; nasa_now?: string;
}
export interface CandidateFile extends PrioritisationSummary {
  top: Candidate[]; pareto_front: Candidate[]; scatter: [number, number, number][];
}
export interface ExampleFile {
  note: string;
  holdout_check: { n_test: number; confusion_matrix: number[][]; f1: number };
  examples: {
    kepoi_name: string; kepler_name: string | null; true_label: string; prediction: string;
    confirmed_probability: number; correct: boolean; inputs: Record<string, number | null>;
  }[];
}

/** Static JSON lives in public/data and is fetched relative to <base href>, so it works on Pages. */
@Injectable({ providedIn: 'root' })
export class DataService {
  readonly results = httpResource<Results>(() => 'data/results.json');
  readonly candidates = httpResource<CandidateFile>(() => 'data/candidates.json');
  readonly examples = httpResource<ExampleFile>(() => 'data/examples.json');
}

export const FEATURE_LABELS: Record<string, string> = {
  koi_model_snr: 'Signal-to-noise', koi_prad: 'Planet radius', koi_duration: 'Transit duration',
  koi_period: 'Orbital period', koi_impact: 'Impact parameter', koi_depth: 'Transit depth',
  koi_srad: 'Star radius', koi_steff: 'Star temperature', koi_insol: 'Insolation',
  koi_teq: 'Equilibrium temp.', koi_slogg: 'Star log g',
};

/** Read a resource's value without throwing when it is in an error state. */
export function valueOf<T>(r: { hasValue(): boolean; value(): T }): T | undefined {
  return r.hasValue() ? r.value() : undefined;
}
